actions.script:
const out = ec.service.sync().name('org.moqui.call.SipDeviceServices.create#SipDevice').parameters({name: name || null,
    deviceProfile: deviceProfile === 'legacy' ? 'legacy' : 'standard'}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse(errors ? {errors, reasonCode: out.reasonCode || null} : {credentials: {username: out.username, password: out.password,
    domain: out.domain, sipPort: out.sipPort, tlsPort: out.tlsPort, transport: out.transport, registrarEnabled: !!out.registrarEnabled}})

const out = ec.service.sync().name('org.moqui.call.SipDeviceServices.rotate#SipDeviceCredential').parameter('sipDeviceId', sipDeviceId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse(errors ? {errors, reasonCode: out.reasonCode || null} : {credentials: {username: out.username, password: out.password,
    domain: out.domain, sipPort: out.sipPort, tlsPort: out.tlsPort, transport: out.transport, registrarEnabled: !!out.registrarEnabled}})

const out = ec.service.sync().name('org.moqui.call.SipDeviceServices.revoke#SipDevice').parameter('sipDeviceId', sipDeviceId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({errors, reasonCode: out.reasonCode || null})
